"""The generated files: a round's note, a project's register and its list of questions,
written whole after every write to the log each is made from."""

from __future__ import annotations

import pytest

from moxi_rounds import (asking, dropping, log, marking, opening, rendering, ruling, showing,
                         shown, state, write)
from moxi_rounds.cli import main

A = "proj-a/a-round"
B = "proj-a/b-round"
SAID = "Do agent-read times follow the settings?"
OTHER = "Is the status line the place for usage?"
THIRD = "Does a parsed row keep its own format?"
ANSWER = "Prose follows the settings; parsed rows do not."
RULED = "Usage is not calculated in the status line; it may be shown there."
LASTING = "Every listing prints who asked a question and when."
NEWER = "Every listing prints who asked a question, and when, in one line."

#: Times a second apart.
T1, T2, T3, T4, T5, T6, T7, T8, T9 = (f"2026-01-02T03:04:0{second}Z"
                                      for second in range(1, 10))
#: A time on a later day.
LATER = "2026-02-03T04:05:06Z"

GENERATED_ROUND = (
    "Generated by moxi rounds from the log of the round {name}, and written again "
    "whole after every write to the round. Edits to this file are lost: write your "
    "own notes on the round in another file of this folder.")
GENERATED_PROJECT = (
    "Generated by moxi rounds from the log of the project proj-a, and written again "
    "whole after every write to it. Edits to this file are lost.")


@pytest.fixture
def rounds(tmp_path, add_project, capsys):
    """The rounds folder of the project `proj-a`, with the rounds `a-round` and
    `b-round` opened in it at `T1`."""
    add_project("proj-a", notes_root=tmp_path / "notes")
    for name in (A, B):
        opening.open_round(name, description="a placeholder round", actor="planner",
                           flow="fix", at=T1)
    capsys.readouterr()
    return tmp_path / "notes" / "rounds"


def ask(target=A, text=SAID, *, at=T2, actor="scout", origin="comms:11", **more):
    return asking.ask(target, text, actor=actor, origin=origin, at=at, **more)


def rule(target=A, *, at, record="comms:12", **more):
    return ruling.rule(target, record=record, actor="planner", at=at, **more)


def note(rounds, slug="a-round"):
    return rounds / slug / rendering.NOTE_FILE


def steps(name=A):
    return ", ".join(step["step"] for step in showing.show(name).state.steps)


def from_the_logs(rounds, slug="a-round"):
    """The three files' text, made here from the logs as they stand."""
    events = log.read(log.round_log(rounds / slug))
    project_events = (log.read(log.project_log(rounds))
                      if log.exists(log.project_log(rounds)) else [])
    return (rendering.note("proj-a", slug, events, project_events),
            rendering.rulings("proj-a", project_events),
            rendering.questions("proj-a", project_events))


def stamps(*paths):
    return [(path.read_bytes(), path.stat().st_mtime_ns) for path in paths]


# -- a round's note ----------------------------------------------------------------------

