def test_a_note_lists_what_showing_the_round_gives(rounds, capsys):
    ask()
    rule(item="Q1", text=ANSWER, at=T3)
    assert main(["show", A]) == 0
    printed = capsys.readouterr().out
    text = note(rounds).read_text(encoding="utf-8")
    found = showing.data(showing.show(A))

    for question in found["questions"]:
        assert f"- {question['id']}: {question['text']}" in text
        assert f"  {question['id']}: {question['text']}" in printed
    for one in found["rulings"]:
        assert f"- {one['id']}: {one['text']}" in text
        assert f"  {one['id']}: {one['text']}" in printed
    assert [part.title for part in rendering.PARTS] == [
        "Flow", "Questions", "Rulings", "Verdicts", "History"]
    headings = [line[3:] for line in text.splitlines() if line.startswith("## ")]
    assert headings == [part.title for part in rendering.PARTS]


def test_the_date_of_a_note_is_that_of_the_rounds_newest_event(rounds):
    ask(at=LATER)
    assert "updated: 2026-02-03\n" in note(rounds).read_text(encoding="utf-8")
    assert "updated: 2026-01-02\n" in note(rounds, "b-round").read_text(encoding="utf-8")


def test_a_description_that_is_not_plain_text_is_quoted_in_the_header(rounds):
    opening.open_round("proj-a/c-round", description='it says: "go" # now',
                       actor="planner", flow="fix", at=T1)
    lines = note(rounds, "c-round").read_text(encoding="utf-8").splitlines()
    assert lines[5] == r'description: "it says: \"go\" # now"'
    assert 'it says: "go" # now' in lines


def test_a_note_names_no_folder_of_the_machine_it_was_written_on(rounds, tmp_path):
    ask()
    ask("proj-a", text=OTHER)
    rule("proj-a", text=LASTING, at=T3)
    for path in (note(rounds), rounds / "rulings.md", rounds / "questions.md"):
        assert str(tmp_path) not in path.read_text(encoding="utf-8")


def test_a_sentence_of_several_lines_stays_inside_its_item(rounds):
    rule(text="Usage is shown.\nIt is not calculated there.", at=T2)
    text = note(rounds).read_text(encoding="utf-8")
    assert "- C1: Usage is shown.\n  It is not calculated there.\n  - record:" in text


# -- a project's register and its list ---------------------------------------------------

def test_the_register_is_the_rulings_of_substance_with_the_replaced_ones_marked(rounds):
    ask("proj-a", text=OTHER)
    rule(text=LASTING, standing=True, scope="proj-a:packages/ui/**,proj-b", at=T3)
    rule("proj-a", text=NEWER, supersedes="S1", reason="one line reads faster",
         record="comms:13", at=T4)
    rule("proj-a", item="P1", text=ANSWER, record="comms:14", at=T5)
    rule("proj-a", text=RULED, record="comms:15", at=T6)
    rule("proj-a", item="revoke:S4", record="comms:16", at=T7)
    shown.mark("proj-a", "S2", actor="planner", record="comms:21", at=T8)
    rule("proj-a", item=f"readback={T5}", record="comms:30", at=T9)

    assert (rounds / "rulings.md").read_text(encoding="utf-8") == f"""\
---
type: rulings
project: proj-a
description: "The standing rulings of proj-a"
tags: [rulings]
updated: 2026-01-02
---

{GENERATED_PROJECT}

# Rulings of proj-a

4 entries, 2 standing

## S1 (replaced by S2)

{LASTING}

- record: comms:12
- by: planner
- at: {T3}
- scope: proj-a:packages/ui/**,proj-b
- shown: read back through {T5}

## S2

{NEWER}

- record: comms:13
- by: planner
- at: {T4}
- replaces: S1
- shown: comms:21
- reason: one line reads faster

## S3

{ANSWER}

- answers P1: {OTHER}
- record: comms:14
- by: planner
- at: {T5}
- shown: read back through {T5}

## S4 (taken back by S5)

{RULED}

- record: comms:15
- by: planner
- at: {T6}
- not shown
"""


def test_an_act_on_the_process_is_no_entry_of_the_register(rounds):
    ask("proj-a", text=OTHER)
    ask("proj-a", text=THIRD)
    rule("proj-a", text=LASTING, at=T3)
    rule("proj-a", item="park:P1", at=T4)
    rule("proj-a", item="withdraw:P2", at=T5)
    rule("proj-a", item=f"readback={T3}", at=T6)

    text = (rounds / "rulings.md").read_text(encoding="utf-8")
    assert [line for line in text.splitlines() if line.startswith("## ")] == ["## S1"]
    assert "1 entry, 1 standing\n" in text
    for act in ("park:", "withdraw:", "readback="):
        assert act not in text
    # They are rulings of the project all the same.
    assert [event.get("id") for event in log.read(log.project_log(rounds))
            if event["type"] == "ruling.recorded"] == ["S1", "S2", "S3", "S4"]


def test_a_register_with_no_ruling_of_substance_says_so(rounds):
    ask("proj-a", text=OTHER)
    text = (rounds / "rulings.md").read_text(encoding="utf-8")
    assert text.endswith("# Rulings of proj-a\n\nNo entry.\n")


