def test_a_project_with_nothing_recorded_on_it_has_no_file_of_its_own(rounds):
    ask()
    rule(text=RULED, at=T3)
    assert sorted(path.name for path in rounds.iterdir()) == ["a-round", "b-round"]


# -- written on every write --------------------------------------------------------------

def test_every_write_to_a_round_writes_its_note_again(rounds):
    writes = [
        lambda: ask(),
        lambda: ask(text=OTHER, at=T3),
        lambda: rule(item="Q1", text=ANSWER, at=T4),
        lambda: rule(item="park:Q2", at=T5),
        lambda: marking.reopen(A, "Q2", actor="helper", at=T6),
        lambda: shown.mark(A, "C1", actor="planner", record="comms:21", at=T7),
        lambda: rule(text=RULED, at=T8),
    ]
    seen = [note(rounds).read_bytes()]
    for one in writes:
        one()
        text = note(rounds).read_text(encoding="utf-8")
        assert text == from_the_logs(rounds)[0]
        assert text.encode() not in seen
        seen.append(text.encode())


def test_every_write_to_a_projects_log_writes_its_two_files_again(rounds):
    writes = [
        lambda: ask("proj-a", text=SAID),
        lambda: rule("proj-a", text=LASTING, at=T3),
        lambda: rule(text=NEWER, standing=True, supersedes="S1", at=T4),
        lambda: rule("proj-a", item="P1", text=ANSWER, at=T5),
        lambda: shown.mark("proj-a", "S2", actor="planner", record="comms:21", at=T6),
    ]
    seen = []
    for one in writes:
        one()
        both = [(rounds / name).read_text(encoding="utf-8")
                for name in ("rulings.md", "questions.md")]
        assert both == list(from_the_logs(rounds)[1:])
        assert both not in seen
        seen.append(both)
    # The ruling recorded from the round wrote the round's log too, so its note.
    assert note(rounds).read_text(encoding="utf-8") == from_the_logs(rounds)[0]


def test_a_write_to_one_log_leaves_the_files_of_the_others_as_they_were(rounds):
    ask("proj-a", text=SAID)
    ask(B, text=OTHER)
    others = (rounds / "rulings.md", rounds / "questions.md", note(rounds, "b-round"))
    before = stamps(*others)

    ask()
    rule(text=RULED, at=T3)
    assert stamps(*others) == before

    kept = stamps(note(rounds), note(rounds, "b-round"))
    rule("proj-a", text=LASTING, at=T4)
    assert stamps(note(rounds), note(rounds, "b-round")) == kept


def read_back(time, *, at=LATER):
    return ruling.rule("proj-a", item=f"readback={time}", record="comms:90",
                       actor="planner", at=at)


def test_a_read_back_writes_again_the_note_of_every_round_open_or_ended(rounds):
    rule(text=RULED, at=T3)
    rule(B, text=LASTING, at=T4)
    dropping.drop(B, by="operator", record="comms:30", actor="planner", at=T5)
    for slug in ("a-round", "b-round"):
        assert "  - not shown\n" in note(rounds, slug).read_text(encoding="utf-8")

    assert not read_back(T4).failed

    for slug in ("a-round", "b-round"):
        text = note(rounds, slug).read_text(encoding="utf-8")
        assert text == from_the_logs(rounds, slug)[0]
        assert f"  - shown: read back through {T4}\n" in text
        assert "not shown" not in text
    # No log but the project's gained an event.
    assert [len(log.read(log.round_log(rounds / slug)))
            for slug in ("a-round", "b-round")] == [2, 3]


def test_a_read_back_leaves_a_note_saying_not_shown_only_of_a_later_ruling(rounds):
    rule(text=RULED, at=T3)
    rule(text=LASTING, at=T5)

    read_back(T3)

    text = note(rounds).read_text(encoding="utf-8")
    assert text.count(f"shown: read back through {T3}") == 1
    assert text.count("  - not shown\n") == 1


def test_a_read_back_writes_into_no_folder_that_holds_no_log(rounds):
    rule(text=RULED, at=T3)
    theirs = rounds / "c-round" / "round-note.md"
    theirs.parent.mkdir()
    theirs.write_bytes(b"kept by another tool\n")
    (rounds / "d-round").mkdir()
    (rounds / "drafts").mkdir()
    before = stamps(theirs)

    assert not read_back(T3).failed

    assert stamps(theirs) == before
    assert [path.name for path in theirs.parent.iterdir()] == ["round-note.md"]
    assert list((rounds / "d-round").iterdir()) == []
    assert list((rounds / "drafts").iterdir()) == []


def test_a_read_back_passes_over_a_round_whose_log_cant_be_read(rounds):
    rule(text=RULED, at=T3)
    with log.round_log(rounds / "b-round").open("ab") as file:
        file.write(b"not an event\n")
    before = stamps(note(rounds, "b-round"), log.round_log(rounds / "b-round"))

    assert not read_back(T3).failed

    assert stamps(note(rounds, "b-round"), log.round_log(rounds / "b-round")) == before
    assert f"shown: read back through {T3}" in note(rounds).read_text(encoding="utf-8")


def test_a_note_a_read_back_cant_write_keeps_the_read_back_and_the_other_notes(
        rounds, capsys):
    rule(text=RULED, at=T3)
    rule(B, text=LASTING, at=T4)
    note(rounds).unlink()
    (note(rounds) / "in-the-way").mkdir(parents=True)

    assert main(["rule", "proj-a", f"readback={T4}", "--record", "comms:90",
                 "--as", "planner"]) == 0
    assert "warning: recorded" in capsys.readouterr().err

    assert log.read(log.project_log(rounds))[-1]["rules"] == f"readback={T4}"
    assert f"shown: read back through {T4}" in note(rounds, "b-round").read_text(
        encoding="utf-8")
    assert (rounds / "rulings.md").read_text(encoding="utf-8") == \
        from_the_logs(rounds)[1]


def test_a_read_back_does_not_wait_long_for_a_round_another_process_holds(
        rounds, holder, monkeypatch):
    rule(text=RULED, at=T3)
    rule(B, text=LASTING, at=T4)
    monkeypatch.setattr(rendering, "NOTE_WAIT_S", 0.2)
    holder(write.round_lock("proj-a", "a-round"))
    before = stamps(note(rounds))

    read = read_back(T4)

    # The round another verb is writing is left to it, and said to be left.
    assert [type(error).__name__ for _callback, error in read.failed] == ["Locked"]
    assert stamps(note(rounds)) == before
    assert f"shown: read back through {T4}" in note(rounds, "b-round").read_text(
        encoding="utf-8")
    assert log.read(log.project_log(rounds))[-1]["rules"] == f"readback={T4}"


def test_a_ruling_that_is_no_read_back_leaves_every_note_as_it_was(rounds):
    rule(text=RULED, at=T3)
    kept = stamps(note(rounds), note(rounds, "b-round"))

    rule("proj-a", text=LASTING, at=T4)
    marking_shown = main(["mark", "proj-a", "S1", "--shown", "--record", "comms:91",
                          "--as", "planner"])

    assert marking_shown == 0
    assert stamps(note(rounds), note(rounds, "b-round")) == kept


def test_a_mark_of_a_standing_ruling_writes_the_register_again(rounds, capsys):
    rule("proj-a", text=LASTING, at=T4)
    assert "- not shown\n" in (rounds / "rulings.md").read_text(encoding="utf-8")

    assert main(["mark", "proj-a", "S1", "--shown", "--record", "comms:91",
                 "--as", "planner"]) == 0

    text = (rounds / "rulings.md").read_text(encoding="utf-8")
    assert text == from_the_logs(rounds)[1]
    assert "- shown: comms:91\n" in text and "not shown" not in text


def test_a_hand_edit_is_gone_after_the_next_write(rounds):
    ask("proj-a", text=SAID)
    for path in (note(rounds), rounds / "rulings.md", rounds / "questions.md"):
        path.write_text(path.read_text(encoding="utf-8") + "\nmy own line\n",
                        encoding="utf-8")

    ask()
    ask("proj-a", text=OTHER, at=T3)
    for path, text in zip((note(rounds), rounds / "rulings.md",
                           rounds / "questions.md"), from_the_logs(rounds),
                          strict=True):
        assert path.read_text(encoding="utf-8") == text
        assert "my own line" not in text


def test_someones_own_file_in_the_folder_is_left_as_it_is(rounds):
    own = (rounds / "a-round" / "notes-on-it.md", rounds / "a-round" / "design.md",
           rounds / "thoughts.md")
    for path in own:
        path.write_text("my own prose about the round\n", encoding="utf-8")
    before = stamps(*own)

    ask()
    rule(text=RULED, at=T3)
    ask("proj-a", text=OTHER)
    rule("proj-a", text=LASTING, at=T3)

    assert stamps(*own) == before
    assert sorted(path.name for path in (rounds / "a-round").iterdir()) == [
        "design.md", "notes-on-it.md", "round-note.md", "round.jsonl"]
    assert sorted(path.name for path in rounds.iterdir()) == [
        "a-round", "b-round", "project.jsonl", "questions.md", "rulings.md",
        "thoughts.md"]


def test_a_folder_with_no_log_is_never_written_into(rounds):
    theirs = rounds / "c-round" / "round-note.md"
    theirs.parent.mkdir()
    theirs.write_bytes(b"kept by another tool\n")
    before = stamps(theirs)
    where = write.Where("proj-a", rounds, "c-round")
    opened = [{"v": 1, "n": 1, "at": T1, "actor": "planner", "type": "round.opened",
               "description": "a placeholder round", "flow": "fix", "steps": []}]
    view = write.View(where=where, events=[], state=state.fold([]), project_events=[],
                      project_state=state.fold([]))

    rendering.on_append(write.Written(where=where, view=view, events=tuple(opened),
                                      round_events=tuple(opened), project_events=()))

    assert stamps(theirs) == before
    assert [path.name for path in theirs.parent.iterdir()] == ["round-note.md"]


# -- the same log, the same bytes --------------------------------------------------------

def test_the_same_logs_give_the_same_bytes(rounds):
    ask()
    rule(item="Q1", text=ANSWER, at=T3)
    ask("proj-a", text=OTHER)
    rule("proj-a", text=LASTING, at=T3)
    rule(text=RULED, at=T4)
    paths = (note(rounds), rounds / "rulings.md", rounds / "questions.md")
    first = [path.read_bytes() for path in paths]

    assert [text.encode() for text in from_the_logs(rounds)] == first
    assert [text.encode() for text in from_the_logs(rounds)] == first

    # A write that appends nothing makes each file again, from logs that are the same.
    for path in paths:
        path.unlink()
    home = write.Where("proj-a", rounds, "a-round")
    write.record(home, actor="helper", event=lambda view, result: None)
    write.record(write.Where("proj-a", rounds), actor="helper",
                 event=lambda view, result: None)
    assert [path.read_bytes() for path in paths] == first


def test_the_same_events_in_another_folder_give_the_same_note(rounds, tmp_path):
    ask()
    rule(text=RULED, at=T3)
    events = log.read(log.round_log(rounds / "a-round"))
    elsewhere = tmp_path / "elsewhere" / "a-round"
    elsewhere.mkdir(parents=True)
    for event in events:
        log.append(log.round_log(elsewhere), event["type"],
                   {key: value for key, value in event.items()
                    if key not in ("v", "n", "at", "actor", "type")},
                   actor=event["actor"], at=event["at"])
    again = log.read(log.round_log(elsewhere))

    assert rendering.note("proj-a", "a-round", again).encode() == \
        note(rounds).read_bytes()


# -- a file that can't be written --------------------------------------------------------

def test_a_note_that_cant_be_written_keeps_the_event_and_the_next_write_repairs_it(
        rounds, capsys):
    stale = note(rounds).read_bytes()
    note(rounds).unlink()
    # A folder where the file goes: the file can't be put in place.
    (note(rounds) / "in-the-way").mkdir(parents=True)

    asked = ask()
    assert [type(error) for _callback, error in asked.failed] != []
    assert log.read(log.round_log(rounds / "a-round"))[-1]["id"] == "Q1"
    assert note(rounds).is_dir()

    assert main(["ask", A, OTHER, "--from", "comms:11", "--as", "scout"]) == 0
    said = capsys.readouterr()
    assert "Q2" in said.out
    assert "warning: recorded" in said.err
    assert [event.get("id") for event in log.read(log.round_log(rounds / "a-round"))
            ] == [None, "Q1", "Q2"]
    # Nothing half-written is left beside it.
    assert sorted(path.name for path in (rounds / "a-round").iterdir()) == [
        "round-note.md", "round.jsonl"]

    (note(rounds) / "in-the-way").rmdir()
    note(rounds).rmdir()
    assert not rule(text=RULED, at=LATER).failed
    text = note(rounds).read_text(encoding="utf-8")
    assert text == from_the_logs(rounds)[0]
    assert text.encode() != stale
    assert f"- Q1: {SAID}" in text and f"- Q2: {OTHER}" in text


def test_one_file_that_cant_be_written_does_not_keep_the_others_from_being_written(
        rounds):
    (rounds / "rulings.md" / "in-the-way").mkdir(parents=True)

    ruled = rule(text=LASTING, standing=True, at=T2)

    assert len(ruled.failed) == 1
    assert note(rounds).read_text(encoding="utf-8") == from_the_logs(rounds)[0]
    assert (rounds / "questions.md").read_text(encoding="utf-8") == \
        from_the_logs(rounds)[2]
    assert log.read(log.project_log(rounds))[-1]["id"] == "S1"
